Mesh<Point, double> result;

std::unordered_map<RT::Cell_handle, std::vector<Point>> cell_polygons;

for (auto eit = rt.edges_begin(); eit != rt.edges_end(); ++eit) {
    if (is_small_edge(rt, *eit, threshold)) continue;

    RT::Cell_handle c1 = eit->first;
    RT::Cell_handle c2 = c1->neighbor(eit->second);

    if (rt.is_infinite(c1) || rt.is_infinite(c2)) continue;

    Point p1 = rt.dual(c1);
    Point p2 = rt.dual(c2);

    cell_polygons[c1].push_back(p2);
    cell_polygons[c2].push_back(p1);
}

for (const auto& [cell, points] : cell_polygons) {
    if (points.size() < 3) continue;

    std::vector<unsigned> indices;
    for (const Point& p : points) {
        result.vertices.push_back(p);
        indices.push_back(static_cast<unsigned>(result.vertices.size() - 1));
    }

    double perimeter = 0.0;
    for (size_t i = 0; i < indices.size(); ++i) {
        size_t j = (i + 1) % indices.size();
        perimeter += std::sqrt(CGAL::squared_distance(
            result.vertices[indices[i]], result.vertices[indices[j]]));
    }

    result.push_back(indices, perimeter);
}

return result;

